/** Gets the encoder for {@link WithdrawReceiptArgs} account data. */
export function getWithdrawReceiptEncoder(): FixedSizeEncoder<WithdrawReceiptArgs> {
  return transformEncoder(
    getStructEncoder([
      ["discriminator", fixEncoderSize(getBytesEncoder(), 8)],
      ["user", getAddressEncoder()],
      ["lpVault", getAddressEncoder()],
      ["pendingShares", getU64Encoder()],
      ["claimableShares", getU64Encoder()],
      ["claimableAssets", getU64Encoder()],
      ["oldestPendingAt", getI64Encoder()],
      ["bump", getU8Encoder()],
    ]),
    (value) => ({ ...value, discriminator: WITHDRAW_RECEIPT_DISCRIMINATOR })
  );
}

/** Gets the decoder for {@link WithdrawReceipt} account data. */
export function getWithdrawReceiptDecoder(): FixedSizeDecoder<WithdrawReceipt> {
  return getStructDecoder([
    ["discriminator", fixDecoderSize(getBytesDecoder(), 8)],
    ["user", getAddressDecoder()],
    ["lpVault", getAddressDecoder()],
    ["pendingShares", getU64Decoder()],
    ["claimableShares", getU64Decoder()],
    ["claimableAssets", getU64Decoder()],
    ["oldestPendingAt", getI64Decoder()],
    ["bump", getU8Decoder()],
  ]);
}

/** Gets the codec for {@link WithdrawReceipt} account data. */
export function getWithdrawReceiptCodec(): FixedSizeCodec<WithdrawReceiptArgs, WithdrawReceipt> {
  return combineCodec(getWithdrawReceiptEncoder(), getWithdrawReceiptDecoder());
}

export function decodeWithdrawReceipt<TAddress extends string = string>(
  encodedAccount: EncodedAccount<TAddress>
): Account<WithdrawReceipt, TAddress>;
export function decodeWithdrawReceipt<TAddress extends string = string>(
  encodedAccount: MaybeEncodedAccount<TAddress>
): MaybeAccount<WithdrawReceipt, TAddress>;
export function decodeWithdrawReceipt<TAddress extends string = string>(
  encodedAccount: EncodedAccount<TAddress> | MaybeEncodedAccount<TAddress>
): Account<WithdrawReceipt, TAddress> | MaybeAccount<WithdrawReceipt, TAddress> {
  return decodeAccount(
    encodedAccount as MaybeEncodedAccount<TAddress>,
    getWithdrawReceiptDecoder()
  );
}

export async function fetchWithdrawReceipt<TAddress extends string = string>(
  rpc: Parameters<typeof fetchEncodedAccount>[0],
  address: Address<TAddress>,
  config?: FetchAccountConfig
): Promise<Account<WithdrawReceipt, TAddress>> {
  const maybeAccount = await fetchMaybeWithdrawReceipt(rpc, address, config);
  assertAccountExists(maybeAccount);
  return maybeAccount;
}

export async function fetchMaybeWithdrawReceipt<TAddress extends string = string>(
  rpc: Parameters<typeof fetchEncodedAccount>[0],
  address: Address<TAddress>,
  config?: FetchAccountConfig
): Promise<MaybeAccount<WithdrawReceipt, TAddress>> {
  const maybeAccount = await fetchEncodedAccount(rpc, address, config);
  return decodeWithdrawReceipt(maybeAccount);
}

export async function fetchAllWithdrawReceipt(
  rpc: Parameters<typeof fetchEncodedAccounts>[0],
  addresses: Array<Address>,
  config?: FetchAccountsConfig
): Promise<Account<WithdrawReceipt>[]> {
  const maybeAccounts = await fetchAllMaybeWithdrawReceipt(rpc, addresses, config);
  assertAccountsExist(maybeAccounts);
  return maybeAccounts;
}

export async function fetchAllMaybeWithdrawReceipt(
  rpc: Parameters<typeof fetchEncodedAccounts>[0],
  addresses: Array<Address>,
  config?: FetchAccountsConfig
): Promise<MaybeAccount<WithdrawReceipt>[]> {
  const maybeAccounts = await fetchEncodedAccounts(rpc, addresses, config);
  return maybeAccounts.map((maybeAccount) => decodeWithdrawReceipt(maybeAccount));
}

